import { isPromise } from '@/utils/is';
import { Button, ButtonProps } from '@arco-design/web-react';
import { useState } from 'react';

export default (props: ButtonProps) => {

    const [loading, setLoading] = useState(() => {

        props.className && console.log('className', props.className)
        return false;
    });

    const onClick = (e) => {
        if(props.onClick){
            const result: Promise<any> = props.onClick(e) as any;
            // console.log('result',typeof result, isPromise(result))
            if(isPromise(result)){
                setLoading(true)
                result.finally(() => {
                    setLoading(false);
                })
            }
        }
    }

    return <Button loading={loading} {...props} onClick={onClick} />
}