import { Form, FormProps, Collapse, CollapseProps, CollapseItemProps, Modal, ModalProps } from "@arco-design/web-react"
import React, { ReactNode, useEffect, useMemo, useState, useImperativeHandle, forwardRef } from "react";
import { FormGenerate, schemaToFormItem } from "react-converter-code"
import { JSONSchemaCustom } from "@/components/schema/interface";
import { isPromise } from "@/utils/is";
import { schemaToJSON } from "@/utils/schema";
import type { FormItem } from "src/components/FormGenerate/interface";
import type { FormGeneragteProps } from "src/components/FormGenerate";
import { useObserver } from "mobx-react-lite";

export interface SchemaFormProps extends FormProps {
    ref?: any;
    schema: JSONSchemaCustom;
    generagteProps?: Partial<FormGeneragteProps>;
    widgets?: FormGeneragteProps['widgets'];
    /**
     * 需要过滤展示的schema 数据
     */
    filterKeys?: string[];
    // 编辑配置
    isEdit?: boolean;
    eidtProps?: {
        // 禁止编辑字段
        disbledKeys?: string[];
        // 编辑模式下隐藏字段
        hideKeys?: string[];
    }
    cols?: FormGeneragteProps['cols'],
    // 标签宽度
    labelWidth?: string | number;
    collapseProps?: CollapseProps;
    collapses?: {
        keys: string[],
        itemProps: CollapseItemProps
    }[]
}
const SchemaForm = forwardRef(({
    form: parentForm,
    schema,
    cols = 12,
    widgets,
    isEdit,
    eidtProps,
    generagteProps,
    collapses,
    collapseProps,
    filterKeys,
    labelWidth = `100px`,
    ...props
}: SchemaFormProps, ref: any) => {


    return useObserver(() => {
        const [form] = parentForm? [parentForm] : Form.useForm();

        const [key, initialValues] = useMemo(() => {
            return [Date.now(), schemaToJSON(schema)];
        }, [schema])
    
        useImperativeHandle(ref, () => {
            return form;
        },[])
    
        const formList = useMemo(() => {
            let list: FormItem[] = [];
            if(!Array.isArray(schema)){
                list = schemaToFormItem(schema)
            }
            if(isEdit && eidtProps){
                const { disbledKeys, hideKeys } = eidtProps;
                if(hideKeys){
                    list = list.filter((o) => !hideKeys.includes(o.field))
                }
                if(disbledKeys){
                    list = list.map((o) => {
                        if(disbledKeys.includes(o.field)){
                            o.fieldProps = {
                                ...o.fieldProps,
                                disabled: true
                            }
                        }
                        return o;
                    })
                }
            }
            return list;
        },[schema, isEdit])
    
        const formGenerateProps = useMemo(() => {
            if(schema && schema.formGenerateProps){
                return { 
                    ...schema.formGenerateProps,
                    ...generagteProps
                }
            }
            return generagteProps;
        },[generagteProps, schema])
    
        const generagte = useMemo(() => {
            if(collapses){
                const collapseRender = collapses.map((o, i) => {
                    return (
                        <Collapse.Item key={i} {...o.itemProps}>
                            <FormGenerate
                                form={form}
                                cols={cols}
                                widgets={widgets}
                                formItemList={formList.filter((item) => o.keys.includes(item.field))}
                                {...formGenerateProps}
                            />
                        </Collapse.Item>
                    )
                })
                return (
                    <Collapse {...collapseProps}>
                        {collapseRender}
                    </Collapse>
                )
            }else {
    
                if(filterKeys){
                    const map =  new Map(formList.map((o) => [o.field, o]));
                    const formItemList = filterKeys.map((k) => map.get(k)).filter((o) => Boolean(o));
                    return (
                        <FormGenerate
                            form={form}
                            cols={cols}
                            widgets={widgets}
                            formItemList={formItemList}
                            {...formGenerateProps}
                        />
                    )
                }
    
                return (
                    <FormGenerate
                        form={form}
                        cols={cols}
                        widgets={widgets}
                        formItemList={formList}
                        {...formGenerateProps}
                    />
                )
            }
        },[formList, filterKeys])
    
        return (
            <Form
                form={form}
                labelCol={{
                    style: { maxWidth: labelWidth }
                }}
                wrapperCol={{
                    style: { flex: '1 0 100px' }
                }}
                key={key}
                {...props}
                initialValues={{
                    ...initialValues,
                    ...props.initialValues,
                }}
            >
                {generagte}
                {props.children}
            </Form>
        )
    })
})

export interface SchemaFormModalProps extends SchemaFormProps {
    trigger?: ReactNode;
    modalProps?: ModalProps;
    onSuccess?: ModalProps['onOk'];
}

export const SchemaFormModal = ({ trigger, onSuccess, modalProps, ...props }: SchemaFormModalProps) => {

    const [visible, setVisible] = useState<boolean>(false);
    const [form] = props.form? [props.form] : Form.useForm();

    useEffect(() => {
        if(!visible){
            form.clearFields();
        }
    },[visible])

    if(!props.schema) return null;
    return (
        <React.Fragment>
            {trigger && React.cloneElement(trigger as any, {
                onClick: () => {
                    setVisible(true);
                }
            })}
            <Modal
                visible={visible}
                title={props.schema.title}
                onCancel={() => {
                    setVisible(false);
                }}
                escToExit
                unmountOnExit
                onOk={() => {
                    if(onSuccess){
                        return form.validate().then((res) => {
                            const result = onSuccess(res) as Promise<any>;
                            if(isPromise(result)){
                                return result.then((res) => {
                                    setVisible(false);
                                }).finally(() => {
                                    if(props.onSubmit){
                                        props.onSubmit(res);
                                    }
                                })
                            }else {
                                setVisible(false)
                                if(props.onSubmit){
                                    props.onSubmit(res);
                                }
                            }
                        })
                        
                    }
                }}
                {...modalProps}
            >
                <SchemaForm 
                    {...props}
                    form={form}
                />
            </Modal>
        </React.Fragment>
    )
}


export interface SchemaFormItemsProps extends FormGeneragteProps {
    schema: JSONSchemaCustom;
}

export const SchemaFormItems = ({ schema, ...props }: SchemaFormItemsProps) => {
    const [key, initialValues] = useMemo(() => {
        return [Date.now(), schemaToJSON(schema)];
    }, [schema])

    const formList = useMemo(() => {
        let list: FormItem[] = [];
        if(!Array.isArray(schema)){
            list = schemaToFormItem(schema)
        }
        return list;
    },[schema])


    return (
        <FormGenerate
            formItemList={formList}
            {...props}
        />
    )
}


export default SchemaForm;