import React, { useMemo, memo, useCallback, useState, useEffect, forwardRef } from 'react';
import { Button, Space, Table, TableProps, Form } from '@arco-design/web-react';
import { Resizable } from 'react-resizable';
import { SortableContainer, SortableElement, SortableHandle } from 'react-sortable-hoc';
import '../style.less';
import _ from 'lodash';
import { IconDragDotVertical } from '@arco-design/web-react/icon';
import classNames from 'classnames';
import { TableFixedMoveProps } from '../interface';

const CustomResizeHandle = forwardRef((props: any, ref: any) => {
  const { handleAxis, ...restProps } = props;
  return (
    <span
      ref={ref}
      className={`react-resizable-handle react-resizable-handle-${handleAxis}`}
      {...restProps}
      onClick={(e) => {
        e.stopPropagation();
      }}
    />
  );
});

const ResizableTitle = (props: any) => {
  const { onResize, width, ...restProps } = props;

  if (!width) {
    return <th {...restProps} />;
  }

  return (
    <Resizable
      width={width}
      height={0}
      handle={<CustomResizeHandle />}
      onResize={onResize}
      draggableOpts={{ enableUserSelectHack: false }}
    >
      <th {...restProps} />
    </Resizable>
  );
};

const DragHandle = SortableHandle(() => (
  <IconDragDotVertical
    style={{
      cursor: 'move',
      color: '#555',
    }}
  />
));
const SortableWrapper = SortableContainer((props) => {
  return <tbody {...props} />;
});
const SortableItem = SortableElement((props) => {
  return <tr {...props} />;
});

const arrayMoveMutate = (array, from, to) => {
  const startIndex = to < 0 ? array.length + to : to;

  if (startIndex >= 0 && startIndex < array.length) {
    const item = array.splice(from, 1)[0];
    array.splice(startIndex, 0, item);
  }
};

const arrayMove = (array, from, to) => {
  array = [...array];
  arrayMoveMutate(array, from, to);
  return array;
};



const TableFixed = (props: TableFixedMoveProps) => {
  const [columns, setColumns] = useState<TableProps['columns']>([]);

  function handleResize(index: number) {
    return (e: any, { size }: any) => {
      setColumns((prevColumns: any) => {
        const nextColumns = [...prevColumns];
        nextColumns[index] = {
          ...nextColumns[index],
          width: size.width,
        };
        return nextColumns;
      });
    };
  }

  const getColumns = useCallback(() => {
    if (!props.columns) return [];
    return props.columns.map((item, index) => {
      return {
        ...item,
        onHeaderCell: (col: any) => ({
          width: col.width,
          onResize: handleResize(index),
        }),
      }
    });
  }, [props.columns]);

  function onSortEnd({ oldIndex, newIndex }) {
    if (oldIndex !== newIndex) {
      const newData = arrayMove([].concat(props.data), oldIndex, newIndex).filter((el) => !!el);
      if(props.onChangeMove){
        props.onChangeMove(newData, oldIndex, newIndex);
      }
    }
  }

  const DraggableContainer = (props) => (
    <SortableWrapper
      useDragHandle
      onSortEnd={onSortEnd}
      helperContainer={() => document.querySelector('.arco-drag-table-container-2 table tbody')}
      updateBeforeSortStart={({ node }) => {
        const tds = node.querySelectorAll('td');
        tds.forEach((td) => {
          td.style.width = td.clientWidth + 'px';
        });
      }}
      {...props}
    />
  );

  const DraggableRow = (props) => {
    const { record, index, ...rest } = props;
    return <SortableItem index={index} {...rest} />;
  };

  

  useEffect(() => {
    setColumns(getColumns());
  }, [props.columns]);

  const components: TableProps['components'] = {
    header: {
      operations: ({ selectionNode, expandNode }) => [
        {
          node: <th />,
          width: 40,
        },
        {
          name: 'expandNode',
          node: expandNode,
        },
        {
          name: 'selectionNode',
          node: selectionNode,
        },
      ],
      th: ResizableTitle,
    },
    body: {
      operations: ({ selectionNode, expandNode }) => [
        {
          node: (
            <td>
              <div className='arco-table-cell'>
                <DragHandle />
              </div>
            </td>
          ),
          width: 40,
        },
        {
          name: 'expandNode',
          node: expandNode,
        },
        {
          name: 'selectionNode',
          node: selectionNode,
        },
      ],
      tbody: DraggableContainer,
      row: DraggableRow,
    }
  };


  return (
    <Table
      borderCell
      components={components}
      {...props}
      className={classNames({
        "table-demo-resizable-column": true,
        "arco-drag-table-container-2": true,
      },props.className)}
      columns={columns}
    />
  );
};

export default memo(TableFixed);
