/**
 * 将数组转换为JSONSchema
 */
export function paramListToJSONSchema(list: any[]): JSONSchema {
  if(!Array.isArray(list)) return undefined;
  // 过滤掉不存在name 值
  const result = list.filter((o) => !o.name);
  // if (list.some((o) => !o.name)) {
  //   throw Error('list 数组中每一项必须需要包含 name');
  // }
  return {
    type: 'object',
    properties: {
      ...result.reduce(
        (obj, item) =>
          _.assign(obj, {
            [item.name]: {
              type: "object",
              description: item.description || item.label || '',
            } as JSONSchema,
          }),
        {}
      ),
    },
  };
}

/**
 *  根据JSONSchema 生成表格列表数据（Table）
 * @param o JSONSchema
 * @param path string
 */
export const schemaToList = (o: JSONSchema, path = ['$'], {
  key = path[0],
  schemaPath = path,
  parent = null
}: {
  key?: string,
  schemaPath?: string[],
  parent?: JSONSchema | null
} = {}) => {
  const params: JSONSchemaItemProps = {
    id: getUuid(),
    type: o.type,
    path: path,
    schemaPath,
    key: key,
    // _parentStore: parent,
    _store: o,
  };
  switch (o.type) {
    case 'array':
      if (o.items) {
        if (!Array.isArray(o.items)) {
          if (o.items.type === 'object' && o.items.properties) {
            const properties: any = o.items.properties;
            const keys = Object.keys(properties);
            params.children = keys.map((key) => {
              return schemaToList(
                properties[key],
                [...path, '0', key],
                {
                  key,
                  parent: o,
                  schemaPath: [...schemaPath, 'items', 'properties', key],
                }
              );
            });
          } else {
            params.children = [
              schemaToList(
                o.items, 
                [...path, '0'],
              {
                key: '0',
                parent: o,
                schemaPath: [...schemaPath, 'items'],
              }),
            ];
          }
        } else {
          params.children = o.items.map((option, i) => {
            return schemaToList(
              option, 
              [...path, i.toString()],
              {
                key: `${i}`, 
                parent: o,
                schemaPath: [...schemaPath, 'items', i.toString()],
            });
          });
        }
      }
      break;
    case 'object':
      if (o.properties) {
        const properties: any = o.properties;
        const keys = Object.keys(properties);
        params.children = keys.map((key) => {
          return schemaToList(
            properties[key],
            [...path, key],
            {
              key,
              parent: o,
              schemaPath: [...schemaPath, 'properties', key]
          });
        });
      }
      break;
  }
  return params;
};


/**
 * 获取展示版完整的data 信息
 */
export const schemaToAllData = (schema: JSONSchema, data: any) => {
  const loop = (obj: JSONSchema, value) => {
    switch(obj.type){
      case "object":
        if(typeof value == 'object' && obj.properties){
          for (const key in obj.properties) {
            value[key] = loop(obj.properties[key], value[key]);
          }
        }
      break;
      case "array":
        if(typeof value == "object" && Array.isArray(value) && obj.items && !Array.isArray(obj.items)){
          return value.map((o) => {
            for (const key in obj.items) {
              o[key] = loop(obj.items[key], o[key]);
            }
            return o;
          })
        }
      break;
      default:
        const { enum: enumList } = obj;
        if(enumList){
          const item = enumList.find((o) => o.value == value);
          return item? item.label : value;
        }
    }
    return value;
  }

  return loop(schema, _.cloneDeep(data));
}


/*
* @name 解析JSONSchema数据 (将JSONSchema转为JSON数据)
* @param json  JSONSchema
* @param data  // jsonSchema 路径变量会根据data值进行替换
*/
export const schemaToJSON = (json: JSONSchema, data?: any, option:{
 // 是否返回空值，undefined值 （默认不返回）
 isNull?: boolean;
} = {}) => {
 if(!json) return json;
 // 新加逻辑，json允许直接输入字符串（此处逻辑，目前用于flow流程节点中，body 参数
 if(typeof json === 'string') return json;
 const value = json.default;
 let val: any = value;
 switch (json.type) {
   case 'string':
     val = value;
     break;
   case 'object':
     const properties = json.properties;
     if (properties) {
       val = {};
       Object.keys(properties).forEach((key) => {
         // 5.6，判断对象是否不存在，undefined （不在返回到json中）
         const objVal = schemaToJSON(properties[key], data);
         if(objVal !== undefined || option.isNull){
           val[key] = objVal;
         }
       });
     }
     break;
   case 'array':
     if(value && Array.isArray(value)){
       val = value
     }else if(json.items){
       if(Array.isArray(json.items)){
         val = json.items.map((o) => schemaToJSON(o, data));
       }else {
         // Array<object> 类型，未指定默认值，返回空数组
         val = [];
         // const item = schemaToJSON(json.items as JSONSchema, data);
         // val = item? [item] : [];
       }
     }
     break;
   case 'integer':
   case 'number':
     val = value;
     break;
   case 'null':
     val = null;
   break;
 }
 return val;
};


/**
 * @name 根据新的对象生产 JSON Schema 数据
 * @param val
 * @param json
 */
export const jsonToSchema = (val: any, json: JSONSchema = {}) => {
  
  const obj: JSONSchema = { type: 'object' };
  const valType = typeof val;
  switch (valType) {
    case 'bigint':
      obj.type = 'integer';
      break;
    case 'boolean':
      obj.type = 'boolean';
      break;
    // case 'function':
    case 'number':
      // if (Math.ceil(val) === val) {
      //   obj.type = 'integer';
      // } else {
        obj.type = 'number';
      // }
      break;
    case 'object':
      obj.type = 'object';
      if (!val) {
        obj.type = 'null';
      } else if (Array.isArray(val)) {
        obj.type = 'array';
        const list = val;
        if(list.length){
          const arr = Array.from(
            new Set(
              list.map((o) => {
                // if(typeof o === 'object' ){
                //     return Object.keys(o).join('.')
                // }
                return typeof o;
              })
            )
          );
          if (arr.length === 1) {
            let listItem = list[0];
            // 对象类型，进行参数合并
            if (typeof listItem === 'object' && !Array.isArray(listItem)) {
              listItem = list.reduce(
                (objs, option) => Object.assign(objs, option),
                {}
              );
            }
            obj.items = jsonToSchema(
              listItem,
              Array.isArray(json?.items) ? json?.items[0] : json?.items
            );
            // 判断如果是对象，根据数组值判断数值类型是否为必填项
            if (obj.items.type === 'object') {
              const properties = obj.items.properties as JSONSchema['properties'];
              if (properties) {
                obj.items.required = Object.keys(properties).filter((ik) =>
                  list.every((o) => ik in o)
                );
              }
            }
          } else {
            obj.items = list.map((o, i) =>
              jsonToSchema(
                o,
                Array.isArray(json?.items)
                  ? json?.items[i]
                  : i === 1
                  ? json?.items
                  : undefined
              )
            );
          }
        }else {
          // 如果是空数组，试着从schema 中集成items 数据
          obj.items = json.items;
        }
      } else {
        const properties: JSONSchema['properties'] = {};
        Object.keys(val).forEach((key) => {
          properties[key] = jsonToSchema(
            val[key],
            json?.properties ? json.properties[key] : undefined
          );
        });
        obj.properties = properties;
      }
      break;
    case 'string':
      obj.type = 'string';
      break;
    // case 'symbol':
    case 'undefined':
      obj.type = 'string';
      break;
  }
  if (json?.type === obj.type) {
    _.assign(obj, _.omit(json, ['properties', 'items']));
  }
  if (valType !== 'object' || Array.isArray(val)) {
    obj.default = val;
  }
  return obj;
};


/**
 *  根据JSONSchema 生成TypeScript类型
 */
export const schemaToTypeScript = (schema: JSONSchema) => {
  let html = '';
  const recursiveJSON = (o: JSONSchema, name = 'Object') => {
    let str = '';
    switch (o.type) {
      case 'array':
      case 'object':
        if (o.properties) {
          str = `interface ${name}Props {\n`;
          const keys = Object.keys(o.properties);
          for (const key of keys) {
            const item = o.properties[key];
            const nameKey = key.charAt(0).toUpperCase() + key.slice(1);
            const result = recursiveJSON(item, nameKey);
            const { description, title } = item || {};
            const required = (o.required || []).includes(key);
            if (title && description ){
              str += '\t\\\*\n';
              str += `\t \* @title ${title}\n`;
              str += `\t \* @description ${description}\n`;
              str += `\t\*\/\n`;
            }if (title || description) {
              str += `\t// ${title || description}\n`;
            }
            str += `\t${key}${required ? ':' : '?:'} ${result};\n`;
          }
          str += `}\n`;
        } else if (o.items) {
          if (Array.isArray(o.items)) {
            str = `[${o.items
              .map((item, index) => recursiveJSON(item, `${name}_${index}_`))
              .join(',')}]`;
          } else {
            if (o.items.type === 'object') {
              recursiveJSON(o.items, name);
              str = `${name}Props[]`;
            } else {
              str = `${recursiveJSON(o.items, name)}[]`;
            }
          }
        }
        break;
      case 'null':
        str = 'null';
        break;
      case 'integer':
      case 'number':
        str = 'number';
        break;
      case 'string':
        str = `string`;
        break;
      case 'boolean':
        str += `boolean`;
        break;
      default:
        str = "string";
    }
    if (o.type === 'object') {
      html += str;
      return `${name}Props`;
    }
    return str;
  };
  recursiveJSON(schema);
  return html;
};



/**
 * 将JSONSchema 转为 Columns对象
 * @param schema 
 * @returns 
 */
export const schemaToTableColumn = (schema: JSONSchema): ProColumn[] => {
  const list = schemaToList(schema).children || [];

  const recursionList = (arr: any[]): ProColumn[] => {
    if(!arr) return [];
    return  arr.map((o) => {
      const { _store, key } = o;
      const { title, type, enum: filters, widget, columnProps, format, fieldProps } = _store;
      if(type == 'object') return null;
      const item: ProColumn = {
        title: title || key,
        // 数字默认靠右展示 其他靠左
        align: ['number', 'integer'].includes(type as string)? 'right' : 'left',
        dataIndex: key,
        widget,
        format,
        fieldProps,
        valueEnum: filters && filters.reduce((obj, o) => {
          if(typeof o === 'object'){
            return _.assign(obj, { [o.value]: o });
          }
          return _.assign(obj, { [o]: { label: o } })
        }, {}),
        ...columnProps
        // children: recursionList(o.children)
      }
      // format 特殊类型判断
      switch(format){
        case 'icon':
      }
      return item;
    }).filter((o) => o)
  }

  return recursionList(list);
}