/**
 * @name rules 指定验证规则
 * https://github.com/Tencent/APIJSON/blob/master/Document.md
 * 
 * @条件匹配 !、>、>=、<、<=、
 * "id: 3" 匹配 id = 3 
 * "id>=: 3" 匹配 id >= 3
 * @匹配选项范围 "key{}":[]
 * "id{}":[38710,82001,70793]  匹配id是否符合38710,82001,70793中任意的一个
 * "id{}": "1000,2000,3000"  匹配id是否符合1000,2000,3000中任意的一个
 * "id!{}":[82001,38710] 即id满足 !(id=82001 | id=38710)
 * @匹配条件范围 "key{}":"条件0,条件1..."
 * "id{}":"<=80000,>90000" 等同 key|{}  匹配id符合id<=80000 | id>90000的一个
 * "id&{}": ">80000,<=90000"  即id满足id>80000 & id<=90000
 * "id!{}":"<=80000,>90000" 即id满足 !(id<=80000 | id>90000)
 * @引用判断 key@ | key!@ | key>@ | key>=@ | key<@ | key<=@
 * "password@": "password2" 匹配 password 和 password2 是否相等
 * @模糊匹配 "key$": "%key%",
 * "name$":"%m%" 匹配name中是否包含m
 * "name$":"m%" 匹配name 是否以m开头
 * @正则匹配 "key~":"正则表达式"
 * "name~":"^[0-9]+$" 匹配name 中内容是否全为数字
 * @tip 扩展匹配
 * @格式验证类 "name*": "require" 匹配 name 存在值
 * "name!*": "require" 匹配 name 不存在值
 * -@require 验证某个字段必须，例如："name*": "require"
 * -@number 验证某个字段的值是否为纯数字
 * -@integer 验证某个字段的值是否为整数
 * -@float 验证某个字段的值是否为浮点数字
 * -@boolean 验证某个字段的值是否为布尔值
 * -@array 验证某个字段的值是否为数组
 * -@object 验证某个字段的值是否为对象
 * -@null 验证某个字段的值是否为 null
 * -@undefined 验证某个字段的值是否为  undefined
 */

import { OptionsProps, whereItem } from "@/types/verify";
import * as _ from "lodash";

/**
 * 
 * @param rules 校验规则
 * @returns 返回校验规则where 对象
 */
export const getWhere = (rules: Record<string, any>) => {
    const options: OptionsProps = {
        wheres: {},
        wheresOr: {},
    };
    const errors = [];
    for (const field in rules) {
        const value = rules[field];
        if (field.endsWith('!')){
            options['wheres'][field] = [[ field.slice(0, -1), '!=', value ]];
        } else if (field.endsWith('{}')){
            // 逻辑运算符 & ｜ ！
            const key = field.replace(/((\&|\||\!)?\{\})?$/, '');
            // 逻辑判断取反
            const isInvert = field.endsWith('!{}');
            // 或逻辑添加
            const optionsKey = field.endsWith('&{}')? 'wheres' : 'wheresOr';
            if(Array.isArray(value)){
                options[optionsKey][field] = [[ key, isInvert? 'notIn' : 'in', value]];
            }else if(typeof field === 'string'){
                if(!/\>|\<|\=/g.test(value)){ // 判断是否包含以下逻辑运算符
                    // in 参数字符串形势  '1000,2000,3000'
                    options[optionsKey][field] = [[key, isInvert? 'notIn' : 'in', value.split(',')]];
                }else {
                    const logics: whereItem[1][] = ['=', '!=', '<', '<=', '>', '>='];
                    options[optionsKey][field] = [];
                    value.split(',').forEach((str) => {
                        console.log('str', str)
                        const valueField = str.trim();
                        //运算符 '> = 20, < 10, != 70'
                        const valueLogic: any = /(\>|\<|\!)?\=?/.exec(valueField);
                        if(valueLogic[0] && logics.indexOf(valueLogic[0])){
                            // 参数必须
                            options[optionsKey][field].push([key, valueLogic[0], valueField.replace(/(\>|\<|\!)?\=?/, '')]);
                        }else {
                            errors.push(`[ERROR] ${field}: "${valueField}" 字段操作符检测失败, 操作符支持 >|>=|<|<=|!=, "${valueLogic[0]}"`);
                        }
                    });
                }
            }else {
                errors.push(`[ERROR] ${field} value type error,should be introduced into type String|Array`);
            }
        } else if (field.endsWith('$')) {
            // LINK
            options['wheres'][field] = [[ field.slice(0, -1), 'link' , value ]];
        } else if (field.endsWith('>=')){
            options['wheres'][field] = [[ field.slice(0, -2), '>=', value]];
        } else if (field.endsWith('!=')){
            options['wheres'][field] = [[ field.slice(0, -2), '!=', value]];
        } else if (field.endsWith('<=')){
            options['wheres'][field] = [[ field.slice(0, -2), '<=', value]];
        } else if (field.endsWith('=')){
            options['wheres'][field] = [[ field.slice(0, -1), '=', value]];
        } else if (field.endsWith('>')){
            options['wheres'][field] = [[ field.slice(0, -1), '>', value]];
        } else if (field.endsWith('<')){
            options['wheres'][field] = [[ field.slice(0, -1), '<', value]];
        } else if (field.endsWith('~')) {
            // REGEXP
            options['wheres'][field] = [[ field.slice(0, -1), 'regexp', value]];
        } else if (field.endsWith('%')) {
            // BETWEEN
            const normalizedField = field.substr(0, field.length - 1)
            if(Array.isArray(value)){
                options['wheres'][field] = [[ normalizedField, 'between', value ]];
            } else if (value.split(',').length == 2) {
                options['wheres'][field] = [[ normalizedField, 'between', value.split(',')]];
            }else {
                errors.push(`[ERROR] invalid data range value at "${field}", with value "${value}", it should be TWO string value joined with symbol ",".`)
            }
        } else if (field.endsWith('@')) {
            if (field.endsWith('<=@')){
                options['wheres'][field] = [[field.slice(0,-3), '<=@', value]]
            } else if (field.endsWith('>=@')){
                options['wheres'][field] = [[field.slice(0,-3), '>=@', value]]
            } else if (field.endsWith('<@')){
                options['wheres'][field] = [[field.slice(0,-2), '<@', value]]
            } else if (field.endsWith('>@')){
                options['wheres'][field] = [[field.slice(0,-2), '>@', value]]
            } else if (field.endsWith('!@')){
                options['wheres'][field] = [[field.slice(0,-2), '!=@', value]]
            } else {
                options['wheres'][field] = [[field.slice(0,-1), '@', value]]
            }
        } else {
            options['wheres'][field] = [[field, '=', value]]
        }
    }

    return { options, errors }
}

const isWhere = (o: whereItem, json: any) => {
    const [fieldKey, logic, fieldValue] = o;
    let data = _.get(json, fieldKey);
    switch(logic){
        case 'between':
            if(Array.isArray(fieldValue)){
                const [value1, value2] = fieldValue;
                return data >= value1 && data <= value2;
            }else {
                return false;
            }
        case 'in':
            if(Array.isArray(fieldValue)){
                return fieldValue.includes(data)
            }else {
                return false;
            }
        case 'link':
            if(typeof fieldValue === 'string'){
                const link = new RegExp(`^${fieldValue.replace(/\%/g,'.*')}$`);
                return data.search(link) !== -1;
            }else {
                return false;
            }
        case 'notIn':
            if(Array.isArray(fieldValue)){
                return !fieldValue.includes(data)
            }else {
                return false;
            }
        case 'regexp':
            const regexp = new RegExp(fieldValue);
            return regexp.test(data);
        default: {
            let value = fieldValue;
            let operator = logic.replace('@', '');
            if(logic.indexOf('@') !== -1){
               value =  _.get(json, fieldValue)
            }
            switch(operator){
                case '!=':
                    return data != value;
                case '=':
                    return data == value;
                case '>':
                    return data > value;
                case '<':
                    return data < value;
                case '>=':
                    return data >= value;
                case '<=':
                    return data <= value;
            }
        }
    }
}


/**
 * @param rules 定义验证规则
 * @param data 待验证的数据
 */
export const isVerify = (
    rules: Record<string, any>,
    json: Record<string, any>
) => {

    const { errors, options} = getWhere(rules);
    return new Promise((resolve, reject) => {
        if(errors.length){
            return reject(errors)
        }
        let whereList: whereItem[] = [];
        let whereOrList: whereItem[] = [];
        const whereOrKeys = Object.keys(options.wheresOr || {});
        if(whereOrKeys.length){
            // where or 判断
            whereOrList = whereOrList.concat(
                whereOrKeys.reduce((data, key) => {
                    return data.concat(options.wheresOr[key])
                },[])
            )
        }
        const whereKeys = Object.keys(options.wheres || {});
        if(whereKeys.length || whereOrKeys.length){
            // where and 判断
            whereList = whereList.concat(
                whereKeys.reduce((data, key) => {
                    return data.concat(options.wheres[key])
                },[])
            );
            if(whereList.every((o) => {
                return isWhere(o, json)
            })){
                // 判断是否有or 条件
                if(whereOrList.length){
                    // or 条件般的成功
                    if(whereOrList.some((o) => isWhere(o, json))){
                        resolve(true)
                    }else {
                        reject(false)
                    };
                }else {
                    // 没有验证通过
                    resolve(true)
                }
            }else {
                // and 条件失败
                reject(false)
            }
        }else {
            // 没有条件，默认通过
            resolve(true)
        }
    })

}

/**
 * isVerify 同步版本
 */
export const isVerifySync = (
    rules: Record<string, any>,
    json: Record<string, any>
) => {
    const { errors, options} = getWhere(rules);
    if(errors.length){
        return false;
    }
    let result = true;
    let whereList: whereItem[] = [];
    let whereOrList: whereItem[] = [];
    const whereOrKeys = Object.keys(options.wheresOr || {});
    if(whereOrKeys.length){
        // where or 判断
        whereOrList = whereOrList.concat(
            whereOrKeys.reduce((data, key) => {
                return data.concat(options.wheresOr[key])
            },[])
        )
    }
    const whereKeys = Object.keys(options.wheres || {});
    // console.log('whereKeys', options.wheres, json)
    if(whereKeys.length || whereOrKeys.length){
        // where and 判断
        whereList = whereList.concat(
            whereKeys.reduce((data, key) => {
                return data.concat(options.wheres[key])
            },[])
        );
        if(whereList.every((o) => {
            return isWhere(o, json)
        })){
            // 判断是否有or 条件
            if(whereOrList.length){
                // or 条件般的成功
                if(whereOrList.some((o) => isWhere(o, json))){
                    result = true;
                }else {
                    result = false;
                };
            }else {
                // 没有验证通过
                result = true;
            }
        }else {
            // and 条件失败
            result = false;
        }
    }else {
        // 没有条件，默认通过
    }

    // console.log('isVerifySync', rules, { whereList, whereOrList }, json, result)
    return result;
}